function L(id, title, type, c, duration = 12) {
  return {
    id, title, type, duration,
    content: {
      concept: c.concept, whyItMatters: c.why, howTo: c.howTo, example: c.example,
      practice: c.practice, successCriteria: c.success, commonMistakes: c.mistake,
      knowledgeCheck: c.checks,
    },
  };
}
function A(id, questions) {
  return { id, title: 'Module Assessment', type: 'assessment', duration: 10, isAssessment: true, assessment: { passScore: 70, questions } };
}

